const categories: Array<'Todos' | Category> = ['Todos', 'Pokémon', 'Riftbound', 'One Piece', 'Lorcana', 'Yu-Gi-Oh!', 'Accesorios'];
const money = (value: number) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(value);
const readStore = <T,>(key: string, fallback: T): T => {
  try { const value = localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback; } catch { return fallback; }
};

function Header({ cartCount, wishlistCount, user, query, setQuery, cartOpen, setCartOpen, setAuthOpen }: {
  cartCount: number; wishlistCount: number; user: User | null; query: string; setQuery: (v: string) => void;
  cartOpen: boolean; setCartOpen: (v: boolean) => void; setAuthOpen: (v: boolean) => void;
}) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [userMenu, setUserMenu] = useState(false);
  const closeMenu = () => setMenuOpen(false);
  return (
    <header className="sticky top-0 z-40 border-b border-[#34434a] bg-[#12282f]/95 text-[#f5f0e6] backdrop-blur-md">
      <div className="mx-auto flex h-[74px] max-w-[1400px] items-center gap-4 px-5 lg:px-10">
        <a href="#inicio" onClick={closeMenu} className="flex shrink-0 items-center gap-3" data-testid="link-logo">
          <span className="grid h-10 w-10 place-items-center bg-[#d9eb4b] font-display text-lg font-bold text-[#12282f]">E4</span>
          <span className="hidden font-display text-lg font-bold tracking-[-.04em] sm:block">Élite 4 TCG<span className="text-[#d9eb4b]">.</span></span>
        </a>
        <nav className="ml-5 hidden items-center gap-7 text-sm text-[#c2cfca] lg:flex">
          <a href="#catalogo" className="transition-colors hover:text-[#d9eb4b]" data-testid="link-catalogo">Catálogo</a>
          <a href="#seleccion" className="transition-colors hover:text-[#d9eb4b]" data-testid="link-seleccion">Selección</a>
          <a href="#comunidad" className="transition-colors hover:text-[#d9eb4b]" data-testid="link-comunidad">La tienda</a>
        </nav>
        <div className="relative ml-auto hidden w-full max-w-[310px] md:block">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#82918d]" size={17} />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar cartas, accesorios..." className="h-10 w-full rounded-none border border-[#3e5358] bg-[#19353d] pl-10 pr-3 text-sm outline-none placeholder:text-[#82918d] focus:border-[#d9eb4b]" data-testid="input-search-header" />
        </div>
        <div className="ml-auto flex items-center gap-1 sm:gap-2">
          <a href="#wishlist" className="relative hidden p-2 text-[#c2cfca] hover:text-[#d9eb4b] sm:block" data-testid="link-wishlist">
            <Heart size={20} strokeWidth={1.7} />{wishlistCount > 0 && <span className="absolute right-0 top-0 grid h-4 min-w-4 place-items-center bg-[#de674a] px-1 text-[10px] text-white">{wishlistCount}</span>}
          </a>
          <button type="button" onClick={() => setCartOpen(!cartOpen)} className="relative p-2 text-[#c2cfca] hover:text-[#d9eb4b]" data-testid="button-open-cart">
            <ShoppingBag size={21} strokeWidth={1.7} />{cartCount > 0 && <span className="absolute right-0 top-0 grid h-4 min-w-4 place-items-center bg-[#d9eb4b] px-1 text-[10px] font-bold text-[#12282f]">{cartCount}</span>}
          </button>
          <div className="relative">
            <button type="button" onClick={() => user ? setUserMenu(!userMenu) : setAuthOpen(true)} className="hidden items-center gap-2 p-2 text-[#c2cfca] hover:text-[#d9eb4b] sm:flex" data-testid="button-user-menu">
              <UserRound size={20} strokeWidth={1.7} />{user && <ChevronDown size={14} />}
            </button>
            {user && userMenu && <div className="absolute right-0 top-12 w-48 border border-[#3e5358] bg-[#19353d] p-3 text-sm shadow-2xl">
              <p className="border-b border-[#3e5358] pb-2 font-semibold text-[#f5f0e6]">{user.name}</p>
              <p className="py-2 text-xs text-[#9eafaa]">{user.email}</p>
              <a href="#pedidos" className="block pt-1 text-[#d9eb4b]" data-testid="link-user-orders">Mis pedidos</a>
            </div>}
          </div>
          <button type="button" onClick={() => setMenuOpen(!menuOpen)} className="p-2 lg:hidden" aria-label="Abrir menú" data-testid="button-mobile-menu">{menuOpen ? <X size={23} /> : <Menu size={23} />}</button>
        </div>
      </div>
      {menuOpen && <div className="border-t border-[#34434a] bg-[#12282f] px-5 pb-6 pt-4 lg:hidden">
        <div className="relative mb-4 md:hidden"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#82918d]" size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar cartas, accesorios..." className="h-11 w-full border border-[#3e5358] bg-[#19353d] pl-10 text-sm outline-none" data-testid="input-search-mobile" /></div>
        <nav className="grid gap-3 text-lg"><a href="#catalogo" onClick={closeMenu} data-testid="mobile-link-catalogo">Catálogo</a><a href="#seleccion" onClick={closeMenu} data-testid="mobile-link-seleccion">Selección</a><a href="#comunidad" onClick={closeMenu} data-testid="mobile-link-comunidad">La tienda</a><button type="button" onClick={() => { setAuthOpen(true); closeMenu(); }} className="text-left text-[#d9eb4b]" data-testid="mobile-button-account">{user ? 'Mi cuenta' : 'Entrar / registrarme'}</button></nav>
      </div>}
    </header>
  );
}

function ProductCard({ product, wishlisted, onOpen, onAdd, onWish }: { product: Product; wishlisted: boolean; onOpen: (p: Product, mode: 'quick' | 'detail') => void; onAdd: (p: Product) => void; onWish: (id: number) => void }) {
  return (
    <article className="group relative flex flex-col border border-[#dcd5c8] bg-[#fbf8f1] p-3 transition-transform duration-300 hover:-translate-y-1 hover:shadow-[7px_7px_0_#d9eb4b]" data-testid={`card-product-${product.id}`}>
      <div className="relative aspect-[4/3] overflow-hidden bg-[#e6e0d4]">
        <img src={product.images[0]} alt={product.name} className="h-full w-full object-cover mix-blend-multiply transition-transform duration-500 group-hover:scale-105" data-testid={`img-product-${product.id}`} />
        <div className="absolute inset-0 bg-gradient-to-t from-[#12282f]/40 to-transparent opacity-60" />
        {product.badge && <span className="absolute left-3 top-3 bg-[#d9eb4b] px-2 py-1 font-mono text-[10px] font-bold uppercase tracking-[.14em] text-[#12282f]">{product.badge}</span>}
        <button type="button" onClick={() => onWish(product.id)} className={`absolute right-3 top-3 grid h-9 w-9 place-items-center ${wishlisted ? 'bg-[#de674a] text-white' : 'bg-[#fbf8f1]/90 text-[#12282f]'} transition-colors`} aria-label="Añadir a favoritos" data-testid={`button-wishlist-${product.id}`}><Heart size={17} fill={wishlisted ? 'currentColor' : 'none'} /></button>
        <button type="button" onClick={() => onOpen(product, 'quick')} className="absolute bottom-3 left-3 flex items-center gap-2 bg-[#12282f] px-3 py-2 text-xs font-bold text-[#f5f0e6] opacity-0 transition-opacity group-hover:opacity-100" data-testid={`button-quick-view-${product.id}`}><Eye size={15} /> Vista rápida</button>
      </div>
      <div className="flex flex-1 flex-col px-1 pt-4">
        <p className="font-mono text-[10px] uppercase tracking-[.16em] text-[#de674a]">{product.category}</p>
        <button type="button" onClick={() => onOpen(product, 'detail')} className="mt-2 text-left font-display text-[17px] font-semibold leading-tight text-[#12282f] hover:text-[#de674a]" data-testid={`button-product-detail-${product.id}`}>{product.name}</button>
        <div className="mt-3 flex items-center gap-1 text-[#e09c2c]">{[1, 2, 3, 4, 5].map((n) => <Star key={n} size={12} fill={n <= Math.round(product.rating) ? 'currentColor' : 'none'} />)}<span className="ml-1 font-mono text-[10px] text-[#71807a]">{product.rating}</span></div>
        <div className="mt-4 flex items-end justify-between gap-2">
          <div><span className="font-display text-xl font-bold text-[#12282f]">{money(product.price)}</span>{product.oldPrice && <span className="ml-2 text-xs text-[#88918b] line-through">{money(product.oldPrice)}</span>}</div>
          <button type="button" onClick={() => onAdd(product)} className="grid h-9 w-9 place-items-center bg-[#12282f] text-[#d9eb4b] transition-colors hover:bg-[#de674a] hover:text-white" aria-label="Añadir al carrito" data-testid={`button-add-cart-${product.id}`}><Plus size={18} /></button>
        </div>
        <p className="mt-3 border-t border-[#e5dfd4] pt-3 font-mono text-[10px] uppercase tracking-[.12em] text-[#71807a]">{product.stock < 6 ? `Quedan ${product.stock}` : 'En stock · envío 24/48h'}</p>
      </div>
    </article>
  );
}

function CartDrawer({ open, items, onClose, onChange, onRemove, onCheckout }: { open: boolean; items: CartItem[]; onClose: () => void; onChange: (id: number, amount: number) => void; onRemove: (id: number) => void; onCheckout: () => void }) {
  const [coupon, setCoupon] = useState('');
  const [couponApplied, setCouponApplied] = useState(false);
  const [postal, setPostal] = useState('');
  const [shipping, setShipping] = useState<number | null>(null);
  const subtotal = items.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
  const discount = couponApplied ? subtotal * .1 : 0;
  const finalShipping = shipping ?? (subtotal >= 1200 ? 0 : 149);
  const tax = (subtotal - discount) * .16;
  if (!open) return null;
  return <div className="fixed inset-0 z-50">
    <button type="button" onClick={onClose} className="absolute inset-0 bg-[#12282f]/55 backdrop-blur-[2px]" aria-label="Cerrar carrito" data-testid="button-close-cart-overlay" />
    <aside className="absolute right-0 top-0 flex h-full w-full max-w-[460px] flex-col bg-[#fbf8f1] text-[#12282f] shadow-2xl animate-rise">
      <div className="flex items-center justify-between border-b border-[#dcd5c8] px-6 py-5"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#de674a]">Tu selección</p><h2 className="mt-1 font-display text-2xl font-bold">Carrito <span className="text-[#9aa39b]">({items.length})</span></h2></div><button type="button" onClick={onClose} className="p-2 hover:bg-[#e8e1d5]" data-testid="button-close-cart"><X size={21} /></button></div>
      <div className="scrollbar-hidden flex-1 overflow-y-auto px-6 py-5">
        {items.length === 0 ? <div className="grid h-full place-items-center text-center"><div><div className="mx-auto grid h-16 w-16 place-items-center bg-[#e7edbb] text-[#12282f]"><ShoppingBag size={27} /></div><h3 className="mt-5 font-display text-xl font-bold">Tu mesa está despejada</h3><p className="mt-2 max-w-[240px] text-sm text-[#71807a]">Añade una carta o accesorio y aquí aparecerá tu próxima partida.</p><a href="#catalogo" onClick={onClose} className="mt-5 inline-block bg-[#12282f] px-5 py-3 text-sm font-bold text-[#d9eb4b]" data-testid="link-empty-cart-catalog">Explorar catálogo</a></div></div> : <><div className="space-y-4">{items.map(({ product, quantity }) => <div key={product.id} className="flex gap-3 border-b border-[#e5dfd4] pb-4" data-testid={`row-cart-${product.id}`}><img src={product.images[0]} alt="" className="h-20 w-20 object-cover mix-blend-multiply" /><div className="min-w-0 flex-1"><p className="font-mono text-[9px] uppercase tracking-[.1em] text-[#de674a]">{product.category}</p><h3 className="mt-1 truncate font-display font-semibold">{product.name}</h3><p className="mt-1 font-bold">{money(product.price)}</p><div className="mt-2 flex items-center gap-2"><button type="button" onClick={() => onChange(product.id, -1)} className="grid h-6 w-6 place-items-center border border-[#cfc7ba]" data-testid={`button-decrease-${product.id}`}><Minus size={12} /></button><span className="w-4 text-center font-mono text-xs">{quantity}</span><button type="button" onClick={() => onChange(product.id, 1)} className="grid h-6 w-6 place-items-center border border-[#cfc7ba]" data-testid={`button-increase-${product.id}`}><Plus size={12} /></button><button type="button" onClick={() => onRemove(product.id)} className="ml-auto text-[#9a6b61] hover:text-[#de674a]" aria-label="Eliminar producto" data-testid={`button-remove-${product.id}`}><Trash2 size={15} /></button></div></div></div>)}</div>
          <div className="mt-6 border-y border-[#dcd5c8] py-5"><label className="font-mono text-[10px] uppercase tracking-[.13em] text-[#71807a]">Cupón de bienvenida</label><div className="mt-2 flex gap-2"><input value={coupon} onChange={(e) => setCoupon(e.target.value)} placeholder="ELITE10" className="h-10 min-w-0 flex-1 border border-[#cfc7ba] bg-transparent px-3 text-sm outline-none focus:border-[#12282f]" data-testid="input-coupon" /><button type="button" onClick={() => coupon.trim().toUpperCase() === 'ELITE10' && setCouponApplied(true)} className="h-10 bg-[#e7edbb] px-3 text-xs font-bold" data-testid="button-apply-coupon">Aplicar</button></div>{couponApplied && <p className="mt-2 text-xs font-semibold text-[#27815f]">Cupón aplicado: -10% en tu pedido.</p>}</div>
          <div className="border-b border-[#dcd5c8] pb-5"><label className="font-mono text-[10px] uppercase tracking-[.13em] text-[#71807a]">Calcula tu envío</label><div className="mt-2 flex gap-2"><input value={postal} onChange={(e) => setPostal(e.target.value.replace(/\D/g, ''))} placeholder="Código postal (5 dígitos)" maxLength={5} className="h-10 min-w-0 flex-1 border border-[#cfc7ba] bg-transparent px-3 text-sm outline-none focus:border-[#12282f]" data-testid="input-postal-cart" /><button type="button" onClick={() => postal.length === 5 && setShipping(postal.startsWith('0') || postal.startsWith('1') ? 0 : 149)} className="h-10 border border-[#12282f] px-3 text-xs font-bold" data-testid="button-calculate-shipping">Calcular</button></div>{shipping !== null && <p className="mt-2 text-xs font-semibold">{shipping === 0 ? 'Envío gratis en zona centro.' : `Envío nacional: ${money(shipping)}`}</p>}</div>
          <div className="space-y-2 pt-5 text-sm"><div className="flex justify-between"><span className="text-[#71807a]">Subtotal</span><span>{money(subtotal)}</span></div>{couponApplied && <div className="flex justify-between text-[#27815f]"><span>Descuento</span><span>-{money(discount)}</span></div>}<div className="flex justify-between"><span className="text-[#71807a]">Envío</span><span>{finalShipping === 0 ? 'Gratis' : money(finalShipping)}</span></div><div className="flex justify-between"><span className="text-[#71807a]">IVA (16%)</span><span>{money(tax)}</span></div><div className="flex justify-between border-t border-[#dcd5c8] pt-3 text-lg font-bold"><span>Total estimado</span><span>{money(subtotal - discount + finalShipping + tax)}</span></div></div>
        </>}
      </div>
      {items.length > 0 && <div className="border-t border-[#dcd5c8] bg-[#f2ede3] px-6 py-5"><button type="button" onClick={onCheckout} className="flex w-full items-center justify-between bg-[#de674a] px-5 py-4 font-display font-bold text-white transition-colors hover:bg-[#12282f]" data-testid="button-go-checkout"><span>Continuar al checkout</span><ArrowRight size={18} /></button><p className="mt-3 flex items-center justify-center gap-2 text-center text-[11px] text-[#71807a]"><LockKeyhole size={12} /> Pago protegido · sin sorpresas</p></div>}
    </aside>
  </div>;
}

function ProductModal({ product, mode, onClose, onAdd }: { product: Product | null; mode: 'quick' | 'detail' | null; onClose: () => void; onAdd: (p: Product, quantity?: number) => void }) {
  const [image, setImage] = useState(0);
  const [quantity, setQuantity] = useState(1);
  useEffect(() => { setImage(0); setQuantity(1); }, [product]);
  if (!product || !mode) return null;
  return <div className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-[#12282f]/70 p-4 backdrop-blur-sm">
    <div className="relative my-8 w-full max-w-4xl bg-[#fbf8f1] text-[#12282f] shadow-2xl animate-rise">
      <button type="button" onClick={onClose} className="absolute right-4 top-4 z-10 grid h-9 w-9 place-items-center bg-[#fbf8f1]/90" data-testid="button-close-product-modal"><X size={20} /></button>
      <div className="grid md:grid-cols-[1.05fr_.95fr]">
        <div className="bg-[#e8e2d7] p-5 md:p-8"><div className="aspect-square overflow-hidden bg-[#ddd5c6]"><img src={product.images[image]} alt={product.name} className="h-full w-full object-cover mix-blend-multiply" data-testid="img-product-modal" /></div>{product.images.length > 1 && <div className="mt-3 flex gap-2 overflow-x-auto">{product.images.map((src, index) => <button type="button" key={src} onClick={() => setImage(index)} className={`h-16 w-16 shrink-0 overflow-hidden border-2 ${image === index ? 'border-[#de674a]' : 'border-transparent'}`} data-testid={`button-gallery-${index}`}><img src={src} alt="" className="h-full w-full object-cover mix-blend-multiply" /></button>)}</div>}</div>
        <div className="flex flex-col p-6 md:p-10"><p className="font-mono text-[10px] uppercase tracking-[.17em] text-[#de674a]">{mode === 'quick' ? 'Vista rápida' : 'Ficha de producto'} · {product.category}</p><h2 className="mt-4 max-w-md font-display text-3xl font-bold leading-[.98] md:text-4xl">{product.name}</h2><div className="mt-4 flex items-center gap-2 text-[#e09c2c]"><Star size={15} fill="currentColor" /><span className="font-mono text-xs text-[#71807a]">{product.rating} · 18 reseñas verificadas</span></div><p className="mt-7 text-sm leading-6 text-[#53635d]">{product.description}</p><div className="mt-8 flex items-baseline gap-3"><span className="font-display text-3xl font-bold">{money(product.price)}</span>{product.oldPrice && <span className="text-sm text-[#89938b] line-through">{money(product.oldPrice)}</span>}</div><p className="mt-2 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.12em] text-[#27815f]"><span className="h-2 w-2 rounded-full bg-[#27815f]" /> {product.stock} unidades disponibles</p><div className="mt-auto pt-8"><div className="flex gap-3"><div className="flex h-12 items-center border border-[#cfc7ba]"><button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="grid h-full w-11 place-items-center" data-testid="button-modal-decrease"><Minus size={16} /></button><span className="w-8 text-center font-mono text-sm">{quantity}</span><button type="button" onClick={() => setQuantity(Math.min(product.stock, quantity + 1))} className="grid h-full w-11 place-items-center" data-testid="button-modal-increase"><Plus size={16} /></button></div><button type="button" onClick={() => { onAdd(product, quantity); onClose(); }} className="flex h-12 flex-1 items-center justify-center gap-3 bg-[#12282f] font-display font-bold text-[#d9eb4b] transition-colors hover:bg-[#de674a] hover:text-white" data-testid="button-modal-add-cart">Añadir a la colección <ShoppingBag size={17} /></button></div></div></div>
      </div>
    </div>
  </div>;
}

function AuthModal({ onClose, onLogin }: { onClose: () => void; onLogin: (user: User) => void }) {
  const [register, setRegister] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const submit = () => { if (register && name.trim().length < 2) return setError('Escribe tu nombre para crear la cuenta.'); if (!email.includes('@')) return setError('Introduce un email válido.'); if (password.length < 6) return setError('La contraseña necesita al menos 6 caracteres.'); onLogin({ name: register ? name.trim() : email.split('@')[0], email }); };
  return <div className="fixed inset-0 z-[60] grid place-items-center bg-[#12282f]/75 p-4 backdrop-blur-sm"><div className="relative w-full max-w-md bg-[#fbf8f1] p-7 text-[#12282f] shadow-2xl sm:p-10 animate-rise"><button type="button" onClick={onClose} className="absolute right-4 top-4 p-2" data-testid="button-close-auth"><X size={19} /></button><p className="font-mono text-[10px] uppercase tracking-[.16em] text-[#de674a]">Área de coleccionista</p><h2 className="mt-3 font-display text-3xl font-bold">{register ? 'Crea tu cuenta' : 'Qué bueno verte'}</h2><p className="mt-2 text-sm text-[#71807a]">{register ? 'Guarda favoritos y sigue tus pedidos.' : 'Entra para continuar con tu compra.'}</p><div className="mt-6 flex border-b border-[#dcd5c8]"><button type="button" onClick={() => { setRegister(false); setError(''); }} className={`border-b-2 px-1 pb-3 text-sm font-bold ${!register ? 'border-[#de674a]' : 'border-transparent text-[#71807a]'}`} data-testid="button-login-tab">Iniciar sesión</button><button type="button" onClick={() => { setRegister(true); setError(''); }} className={`ml-6 border-b-2 px-1 pb-3 text-sm font-bold ${register ? 'border-[#de674a]' : 'border-transparent text-[#71807a]'}`} data-testid="button-register-tab">Registrarme</button></div><div className="mt-6 space-y-4">{register && <label className="block text-sm font-semibold">Nombre<input value={name} onChange={(e) => setName(e.target.value)} className="mt-2 h-11 w-full border border-[#cfc7ba] bg-transparent px-3 outline-none focus:border-[#de674a]" data-testid="input-auth-name" /></label>}<label className="block text-sm font-semibold">Email<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="mt-2 h-11 w-full border border-[#cfc7ba] bg-transparent px-3 outline-none focus:border-[#de674a]" data-testid="input-auth-email" /></label><label className="block text-sm font-semibold">Contraseña<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="mt-2 h-11 w-full border border-[#cfc7ba] bg-transparent px-3 outline-none focus:border-[#de674a]" data-testid="input-auth-password" /></label></div>{error && <p className="mt-3 bg-[#f8ded7] px-3 py-2 text-xs font-semibold text-[#a33f2c]" data-testid="status-auth-error">{error}</p>}<button type="button" onClick={submit} className="mt-6 flex h-12 w-full items-center justify-center gap-2 bg-[#12282f] font-display font-bold text-[#d9eb4b]" data-testid="button-submit-auth">{register ? 'Crear cuenta' : 'Entrar'} <ArrowRight size={17} /></button></div></div>;
}

function CheckoutModal({ onClose, onComplete, user, subtotal }: { onClose: () => void; onComplete: (form: CheckoutForm) => string; user: User; subtotal: number }) {
  const [step, setStep] = useState(1);
  const [errors, setErrors] = useState<string[]>([]);
  const [order, setOrder] = useState('');
  const [form, setForm] = useState<CheckoutForm>({ name: user.name, email: user.email, address: '', city: '', postal: '', method: 'card', card: '', expiry: '', cvv: '' });
  const update = (key: keyof CheckoutForm, value: string) => setForm((prev) => ({ ...prev, [key]: value }));
  const validateShipping = () => { const next: string[] = []; if (!form.name.trim()) next.push('Añade tu nombre.'); if (!form.email.includes('@')) next.push('Revisa tu email.'); if (form.address.trim().length < 5) next.push('Añade una dirección completa.'); if (form.city.trim().length < 2) next.push('Indica tu ciudad.'); if (form.postal.length !== 5) next.push('El código postal debe tener 5 cifras.'); setErrors(next); if (!next.length) setStep(2); };
  const validatePayment = () => { if (form.method === 'card' && (form.card.replace(/\s/g, '').length < 12 || form.expiry.length < 4 || form.cvv.length < 3)) return setErrors(['Completa los datos de tu tarjeta.']); setErrors([]); setStep(3); };
  useEffect(() => { if (step !== 3) return; const timer = window.setTimeout(() => { setOrder(onComplete(form)); setStep(4); }, 2000); return () => window.clearTimeout(timer); }, [step]);
  return <div className="fixed inset-0 z-[60] overflow-y-auto bg-[#f2ede3] text-[#12282f]"><div className="mx-auto min-h-full max-w-5xl px-5 py-6 md:px-10 md:py-10"><div className="flex items-center justify-between"><a href="#inicio" className="flex items-center gap-3 font-display text-xl font-bold" data-testid="checkout-logo"><span className="grid h-9 w-9 place-items-center bg-[#d9eb4b] text-sm">E4</span>Élite 4 TCG.</a>{step !== 4 && <button type="button" onClick={onClose} className="flex items-center gap-2 text-sm font-semibold text-[#71807a]" data-testid="button-close-checkout"><X size={18} /> Cerrar</button>}</div>{step < 3 && <div className="mx-auto mt-12 flex max-w-lg items-center justify-between"><div className={`flex items-center gap-2 text-xs font-bold ${step >= 1 ? 'text-[#de674a]' : 'text-[#9ca39d]'}`}><span className="grid h-7 w-7 place-items-center rounded-full bg-[#de674a] text-white">1</span> Envío</div><div className="h-px flex-1 bg-[#d5cec1] mx-3" /><div className={`flex items-center gap-2 text-xs font-bold ${step >= 2 ? 'text-[#de674a]' : 'text-[#9ca39d]'}`}><span className={`grid h-7 w-7 place-items-center rounded-full ${step >= 2 ? 'bg-[#de674a] text-white' : 'bg-[#d5cec1]'}`}>2</span> Pago</div><div className="h-px flex-1 bg-[#d5cec1] mx-3" /><div className="flex items-center gap-2 text-xs font-bold text-[#9ca39d]"><span className="grid h-7 w-7 place-items-center rounded-full bg-[#d5cec1]">3</span> Confirmación</div></div>}{step === 1 && <div className="mx-auto mt-12 grid max-w-3xl gap-10 md:grid-cols-[1fr_280px]"><div><p className="font-mono text-[10px] uppercase tracking-[.16em] text-[#de674a]">Paso 01 / Envío</p><h1 className="mt-3 font-display text-4xl font-bold">¿Dónde lo enviamos?</h1><div className="mt-7 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold sm:col-span-2">Nombre completo<input value={form.name} onChange={(e) => update('name', e.target.value)} className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-checkout-name" /></label><label className="text-sm font-semibold sm:col-span-2">Email<input value={form.email} onChange={(e) => update('email', e.target.value)} type="email" className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-checkout-email" /></label><label className="text-sm font-semibold sm:col-span-2">Dirección<input value={form.address} onChange={(e) => update('address', e.target.value)} placeholder="Calle, número, piso..." className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-checkout-address" /></label><label className="text-sm font-semibold">Ciudad<input value={form.city} onChange={(e) => update('city', e.target.value)} className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-checkout-city" /></label><label className="text-sm font-semibold">Código postal<input value={form.postal} onChange={(e) => update('postal', e.target.value.replace(/\D/g, ''))} maxLength={5} className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-checkout-postal" /></label></div>{errors.length > 0 && <div className="mt-5 bg-[#f8ded7] p-3 text-sm text-[#a33f2c]" data-testid="status-checkout-errors">{errors.map((error) => <p key={error}>{error}</p>)}</div>}<button type="button" onClick={validateShipping} className="mt-7 flex h-12 w-full items-center justify-center gap-2 bg-[#12282f] font-display font-bold text-[#d9eb4b] sm:w-auto sm:px-8" data-testid="button-next-shipping">Continuar al pago <ArrowRight size={17} /></button></div><OrderAside subtotal={subtotal} /></div>}{step === 2 && <div className="mx-auto mt-12 grid max-w-3xl gap-10 md:grid-cols-[1fr_280px]"><div><button type="button" onClick={() => setStep(1)} className="mb-5 flex items-center gap-2 text-xs font-bold text-[#71807a]" data-testid="button-back-shipping"><RotateCcw size={14} /> Volver a envío</button><p className="font-mono text-[10px] uppercase tracking-[.16em] text-[#de674a]">Paso 02 / Pago</p><h1 className="mt-3 font-display text-4xl font-bold">Elige cómo pagar</h1><div className="mt-7 grid gap-3 sm:grid-cols-3">{([['card', 'Tarjeta', CreditCard], ['transfer', 'Transferencia', Landmark], ['paypal', 'PayPal', WalletCards]] as const).map(([value, label, Icon]) => <button type="button" key={value} onClick={() => update('method', value)} className={`flex flex-col gap-3 border p-4 text-left ${form.method === value ? 'border-[#de674a] bg-[#f8ded7]' : 'border-[#cfc7ba] bg-[#fbf8f1]'}`} data-testid={`button-payment-${value}`}><Icon size={20} /><span className="text-sm font-bold">{label}</span></button>)}</div>{form.method === 'card' && <div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold sm:col-span-2">Número de tarjeta<input value={form.card} onChange={(e) => update('card', e.target.value.replace(/[^\d ]/g, '').slice(0, 19))} placeholder="4242 4242 4242 4242" className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-card-number" /></label><label className="text-sm font-semibold">Caducidad<input value={form.expiry} onChange={(e) => update('expiry', e.target.value)} placeholder="MM/AA" className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-card-expiry" /></label><label className="text-sm font-semibold">CVC<input value={form.cvv} onChange={(e) => update('cvv', e.target.value.replace(/\D/g, '').slice(0, 4))} placeholder="123" className="mt-2 h-12 w-full border border-[#cfc7ba] bg-[#fbf8f1] px-3 outline-none focus:border-[#de674a]" data-testid="input-card-cvv" /></label></div>}{form.method !== 'card' && <p className="mt-6 border border-[#dcd5c8] bg-[#fbf8f1] p-4 text-sm leading-6 text-[#53635d]">{form.method === 'transfer' ? 'Te mostraremos los datos bancarios al confirmar el pedido.' : 'Serás redirigido a PayPal en el siguiente paso.'}</p>}{errors.length > 0 && <div className="mt-5 bg-[#f8ded7] p-3 text-sm text-[#a33f2c]" data-testid="status-payment-errors">{errors.map((error) => <p key={error}>{error}</p>)}</div>}<button type="button" onClick={validatePayment} className="mt-7 flex h-12 w-full items-center justify-center gap-2 bg-[#de674a] font-display font-bold text-white sm:w-auto sm:px-8" data-testid="button-pay-order">Pagar {money(subtotal)} <LockKeyhole size={15} /></button></div><OrderAside subtotal={subtotal} /></div>}{step === 3 && <div className="grid min-h-[70vh] place-items-center text-center"><div><div className="mx-auto grid h-20 w-20 place-items-center bg-[#d9eb4b] text-[#12282f]"><div className="h-8 w-8 animate-spin-slow rounded-full border-4 border-[#12282f]/20 border-t-[#12282f]" /></div><p className="mt-7 font-mono text-[10px] uppercase tracking-[.17em] text-[#de674a]">Procesando con cuidado</p><h1 className="mt-3 font-display text-4xl font-bold">Guardando tu pedido...</h1><p className="mt-3 text-sm text-[#71807a]">Estamos cerrando la caja y preparando la etiqueta.</p></div></div>}{order && <div className="grid min-h-[70vh] place-items-center text-center"><div className="max-w-md"><div className="mx-auto grid h-20 w-20 place-items-center bg-[#d9eb4b]"><Check size={38} /></div><p className="mt-7 font-mono text-[10px] uppercase tracking-[.17em] text-[#de674a]">Pedido confirmado</p><h1 className="mt-3 font-display text-5xl font-bold">Ya está en camino.</h1><p className="mt-4 text-[#53635d]">Gracias, {form.name}. Hemos enviado la confirmación a {form.email}.</p><div className="mt-7 border border-[#dcd5c8] bg-[#fbf8f1] p-5"><p className="font-mono text-[10px] uppercase tracking-[.15em] text-[#71807a]">Número de pedido</p><p className="mt-2 font-display text-2xl font-bold">{order}</p><button type="button" onClick={() => navigator.clipboard?.writeText(order)} className="mt-3 inline-flex items-center gap-2 text-xs font-bold text-[#de674a]" data-testid="button-copy-order"><Copy size={13} /> Copiar número</button></div><button type="button" onClick={onClose} className="mt-7 bg-[#12282f] px-7 py-3 font-bold text-[#d9eb4b]" data-testid="button-finish-checkout">Volver a la tienda</button></div></div>}</div></div>;
}

function OrderAside({ subtotal }: { subtotal: number }) {
  const shipping = subtotal >= 1200 ? 0 : 149;
  const tax = subtotal * .16;
  return <aside className="h-fit border border-[#dcd5c8] bg-[#fbf8f1] p-5"><p className="font-mono text-[10px] uppercase tracking-[.15em] text-[#71807a]">Resumen</p><div className="mt-5 flex justify-between text-sm"><span>Artículos</span><span>{money(subtotal)}</span></div><div className="mt-2 flex justify-between text-sm"><span>Envío nacional</span><span>{shipping ? money(shipping) : 'Gratis'}</span></div><div className="mt-2 flex justify-between text-sm"><span>IVA (16%)</span><span>{money(tax)}</span></div><div className="mt-4 flex justify-between border-t border-[#dcd5c8] pt-4 font-bold"><span>Total</span><span>{money(subtotal + shipping + tax)}</span></div><p className="mt-5 flex gap-2 text-[11px] leading-4 text-[#71807a]"><ShieldCheck size={15} className="shrink-0 text-[#27815f]" /> Tus datos viajan cifrados y nunca guardamos tu tarjeta.</p></aside>;
}

function App() {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<'Todos' | Category>('Todos');
  const [maxPrice, setMaxPrice] = useState(3000);
  const [sort, setSort] = useState('featured');
  const [cart, setCart] = useState<CartItem[]>(() => readStore('mazo-cart', []));
  const [wishlist, setWishlist] = useState<number[]>(() => readStore('mazo-wishlist', []));
  const [user, setUser] = useState<User | null>(() => readStore('mazo-user', null));
  const [cartOpen, setCartOpen] = useState(false);
  const [authOpen, setAuthOpen] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [selected, setSelected] = useState<Product | null>(null);
  const [modalMode, setModalMode] = useState<'quick' | 'detail' | null>(null);
  const [toast, setToast] = useState('');

  useEffect(() => { localStorage.setItem('mazo-cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('mazo-wishlist', JSON.stringify(wishlist)); }, [wishlist]);
  useEffect(() => { if (user) localStorage.setItem('mazo-user', JSON.stringify(user)); else localStorage.removeItem('mazo-user'); }, [user]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 2400); return () => window.clearTimeout(timer); }, [toast]);

  const filteredProducts = useMemo(() => products.filter((product) => product.name.toLowerCase().includes(query.toLowerCase()) && (category === 'Todos' || product.category === category) && product.price <= maxPrice).sort((a, b) => sort === 'price-low' ? a.price - b.price : sort === 'price-high' ? b.price - a.price : sort === 'rating' ? b.rating - a.rating : a.id - b.id), [query, category, maxPrice, sort]);
  const wishlistProducts = useMemo(() => products.filter((product) => wishlist.includes(product.id)), [wishlist]);
  const cartCount = cart.reduce((sum, item) => sum + item.quantity, 0);
  const subtotal = cart.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
  const addToCart = (product: Product, quantity = 1) => { setCart((prev) => { const existing = prev.find((item) => item.product.id === product.id); return existing ? prev.map((item) => item.product.id === product.id ? { ...item, quantity: Math.min(product.stock, item.quantity + quantity) } : item) : [...prev, { product, quantity }]; }); setToast(`${product.name} añadido al carrito`); };
  const changeQuantity = (id: number, amount: number) => setCart((prev) => prev.map((item) => item.product.id === id ? { ...item, quantity: item.quantity + amount } : item).filter((item) => item.quantity > 0 && item.quantity <= item.product.stock));
  const removeItem = (id: number) => setCart((prev) => prev.filter((item) => item.product.id !== id));
  const toggleWish = (id: number) => setWishlist((prev) => prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]);
  const openProduct = (product: Product, mode: 'quick' | 'detail') => { setSelected(product); setModalMode(mode); };
  const openCheckout = () => { if (!user) { setCartOpen(false); setAuthOpen(true); } else { setCartOpen(false); setCheckoutOpen(true); } };
  const onLogin = (nextUser: User) => { setUser(nextUser); setAuthOpen(false); setToast(`Bienvenido, ${nextUser.name}`); if (cart.length) setCheckoutOpen(true); };
  const completeOrder = (form: CheckoutForm) => { const id = `E4-${new Date().getFullYear()}-${Math.floor(100000 + Math.random() * 899999)}`; const orders = readStore<unknown[]>('mazo-orders', []); localStorage.setItem('mazo-orders', JSON.stringify([...orders, { id, form, items: cart, total: subtotal }])); setCart([]); return id; };

  return <div className="noise min-h-[100dvh] bg-[#f5f0e6] text-[#12282f]">
    <Header cartCount={cartCount} wishlistCount={wishlist.length} user={user} query={query} setQuery={setQuery} cartOpen={cartOpen} setCartOpen={setCartOpen} setAuthOpen={setAuthOpen} />
    <main>
      <section id="inicio" className="relative overflow-hidden bg-[#193941] text-[#f5f0e6]">
        <div className="mx-auto grid min-h-[650px] max-w-[1400px] items-center gap-12 px-5 py-16 lg:grid-cols-[1.02fr_.98fr] lg:px-10 lg:py-20">
          <div className="relative z-10 animate-rise"><p className="mb-6 flex items-center gap-3 font-mono text-[10px] uppercase tracking-[.2em] text-[#d9eb4b]"><span className="h-px w-10 bg-[#d9eb4b]" /> Cartas con historia</p><h1 className="max-w-2xl font-display text-[clamp(3.7rem,8vw,7.7rem)] font-bold leading-[.84] tracking-[-.08em]">Colecciona<br /><span className="text-[#d9eb4b]">lo que te</span><br />representa.</h1><p className="mt-8 max-w-md text-base leading-7 text-[#bac9c3]">Singles, producto sellado y accesorios elegidos para quienes saben que una carta nunca es solo una carta.</p><div className="mt-9 flex flex-wrap gap-3"><a href="#catalogo" className="flex items-center gap-3 bg-[#d9eb4b] px-6 py-4 font-display font-bold text-[#12282f] transition-transform hover:-translate-y-1" data-testid="link-hero-catalog"><span>Explorar colección</span><ArrowRight size={18} /></a><a href="#seleccion" className="flex items-center border border-[#829a97] px-6 py-4 font-display font-bold text-[#f5f0e6] hover:border-[#d9eb4b] hover:text-[#d9eb4b]" data-testid="link-hero-selection">Ver favoritos</a></div><div className="mt-14 flex gap-8 border-t border-[#496169] pt-5"><div><p className="font-display text-2xl font-bold">+2.400</p><p className="mt-1 font-mono text-[9px] uppercase tracking-[.12em] text-[#9badA7]">cartas catalogadas</p></div><div><p className="font-display text-2xl font-bold">24/48h</p><p className="mt-1 font-mono text-[9px] uppercase tracking-[.12em] text-[#9badA7]">envío nacional</p></div></div></div>
           <div className="relative mx-auto h-[430px] w-full max-w-[520px] lg:h-[540px]"><div className="absolute right-4 top-4 h-[78%] w-[62%] rotate-[9deg] overflow-hidden border-[10px] border-[#e0d7c5] bg-[#de674a] shadow-[18px_18px_0_#d9eb4b] animate-float"><img src={ursulasTroveImage} alt="Selección de producto sellado de Lorcana" className="h-full w-full object-cover mix-blend-multiply opacity-80" /><div className="absolute inset-4 border border-[#f5f0e6]/60" /><div className="absolute bottom-5 left-5 font-display text-3xl font-bold leading-none text-[#f5f0e6]">ÉLITE<br />4 TCG</div></div><div className="absolute bottom-2 left-2 h-[63%] w-[59%] -rotate-[10deg] overflow-hidden border-[10px] border-[#d9eb4b] bg-[#c6d04e] shadow-[12px_12px_0_#10292f]"><img src={paldeanFatesImage} alt="Caja de Élite Pokémon Destinos de Paldea" className="h-full w-full object-cover mix-blend-multiply opacity-75" /><div className="absolute left-5 top-5 font-mono text-xs font-bold tracking-[.18em] text-[#12282f]">E4 / 04</div></div><div className="absolute bottom-9 right-2 grid h-28 w-28 place-items-center rounded-full border border-[#d9eb4b] text-center font-mono text-[10px] uppercase tracking-[.13em] text-[#d9eb4b]">Sellado<br />con criterio</div></div>
        </div><div className="absolute -bottom-24 -right-20 h-72 w-72 rounded-full border-[50px] border-[#de674a]/30" />
      </section>
      <div className="overflow-hidden border-b border-[#cfc7ba] bg-[#d9eb4b] py-3"><div className="flex min-w-max animate-[marquee_25s_linear_infinite] gap-10 font-mono text-[10px] font-bold uppercase tracking-[.2em] text-[#12282f]"><span>Pokémon</span><span>·</span><span>Riftbound</span><span>·</span><span>One Piece</span><span>·</span><span>Lorcana</span><span>·</span><span>Accesorios para jugar mejor</span><span>·</span><span>Pokémon</span><span>·</span><span>Riftbound</span><span>·</span><span>One Piece</span><span>·</span><span>Lorcana</span></div></div>
      <section id="seleccion" className="mx-auto max-w-[1400px] px-5 py-20 lg:px-10 lg:py-28"><div className="grid gap-10 lg:grid-cols-[.75fr_1.25fr]"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#de674a]">01 / Selección de la semana</p><h2 className="mt-4 max-w-sm font-display text-5xl font-bold leading-[.92] tracking-[-.06em]">Piezas que<br /><em className="font-normal text-[#de674a]">merecen mesa.</em></h2><p className="mt-6 max-w-xs text-sm leading-6 text-[#71807a]">No llenamos estanterías por llenar. Buscamos producto con una buena historia detrás y un lugar claro en tu colección.</p><a href="#catalogo" className="mt-8 inline-flex items-center gap-2 border-b-2 border-[#12282f] pb-2 text-sm font-bold" data-testid="link-selection-catalog">Ver todo el catálogo <ArrowRight size={16} /></a></div><div className="grid gap-4 sm:grid-cols-2">{products.slice(0, 2).map((product) => <ProductCard key={product.id} product={product} wishlisted={wishlist.includes(product.id)} onOpen={openProduct} onAdd={addToCart} onWish={toggleWish} />)}</div></div></section>
      <section id="wishlist" className="border-b border-[#cfc7ba] bg-[#f5f0e6]"><div className="mx-auto max-w-[1400px] px-5 py-16 lg:px-10"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#de674a]">Tu radar</p><h2 className="mt-3 font-display text-4xl font-bold tracking-[-.05em]">Favoritos guardados.</h2></div><p className="text-sm text-[#71807a]">{wishlistProducts.length ? `${wishlistProducts.length} ${wishlistProducts.length === 1 ? 'pieza guardada' : 'piezas guardadas'}` : 'Todavía no has guardado nada.'}</p></div>{wishlistProducts.length > 0 ? <div className="mt-7 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{wishlistProducts.map((product) => <ProductCard key={product.id} product={product} wishlisted onOpen={openProduct} onAdd={addToCart} onWish={toggleWish} />)}</div> : <div className="mt-7 flex flex-col items-start justify-between gap-5 border border-dashed border-[#cfc7ba] px-5 py-7 sm:flex-row sm:items-center"><p className="max-w-md text-sm leading-6 text-[#71807a]">Pulsa el corazón en cualquier producto para tenerlo a mano cuando vuelvas.</p><a href="#catalogo" className="flex items-center gap-2 text-sm font-bold text-[#de674a]" data-testid="link-empty-wishlist-catalog">Buscar favoritos <ArrowRight size={16} /></a></div>}</div></section>
       <section id="catalogo" className="border-y border-[#cfc7ba] bg-[#ede7dc]"><div className="mx-auto max-w-[1400px] px-5 py-20 lg:px-10 lg:py-28"><div className="flex flex-col justify-between gap-7 md:flex-row md:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#de674a]">02 / Catálogo</p><h2 className="mt-3 font-display text-5xl font-bold tracking-[-.06em]">Encuentra tu próxima obsesión.</h2></div><p className="max-w-xs text-sm leading-6 text-[#71807a]">Filtra por universo, precio o simplemente deja que el algoritmo haga lo suyo.</p></div><div className="mt-10 flex flex-col gap-3 border-y border-[#cfc7ba] py-4 lg:flex-row lg:items-center"><div className="relative lg:hidden"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#71807a]" size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar en el catálogo" className="h-11 w-full border border-[#cfc7ba] bg-[#f5f0e6] pl-10 text-sm outline-none focus:border-[#de674a]" data-testid="input-search-catalog" /></div><div className="flex gap-2 overflow-x-auto scrollbar-hidden">{categories.map((item) => <button type="button" key={item} onClick={() => setCategory(item)} className={`whitespace-nowrap px-3 py-2 text-xs font-bold ${category === item ? 'bg-[#12282f] text-[#d9eb4b]' : 'border border-[#cfc7ba] text-[#53635d] hover:border-[#12282f]'}`} data-testid={`button-filter-${item.toLowerCase().replace(' ', '-')}`}>{item}</button>)}</div><div className="flex flex-wrap items-center gap-4 lg:ml-auto"><label className="flex items-center gap-2 text-xs text-[#71807a]">Hasta <span className="font-bold text-[#12282f]">{money(maxPrice)}</span><input type="range" min="10" max="3000" step="25" value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} className="accent-[#de674a]" data-testid="input-price-range" /></label><select value={sort} onChange={(e) => setSort(e.target.value)} className="h-9 border border-[#cfc7ba] bg-[#f5f0e6] px-3 text-xs font-bold outline-none" data-testid="select-sort"><option value="featured">Destacados</option><option value="price-low">Precio: menor</option><option value="price-high">Precio: mayor</option><option value="rating">Mejor valorados</option></select></div></div>{filteredProducts.length > 0 ? <div className="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{filteredProducts.map((product) => <ProductCard key={product.id} product={product} wishlisted={wishlist.includes(product.id)} onOpen={openProduct} onAdd={addToCart} onWish={toggleWish} />)}</div> : <div className="grid min-h-[280px] place-items-center text-center"><div><p className="font-display text-3xl font-bold">No hay cartas aquí.</p><p className="mt-2 text-sm text-[#71807a]">Prueba otra búsqueda o amplía el rango de precio.</p><button type="button" onClick={() => { setQuery(''); setCategory('Todos'); setMaxPrice(3000); }} className="mt-5 border-b-2 border-[#de674a] pb-1 text-sm font-bold" data-testid="button-reset-filters">Limpiar filtros</button></div></div>}</div></section>
      <section id="comunidad" className="bg-[#de674a] text-[#f5f0e6]"><div className="mx-auto grid max-w-[1400px] gap-10 px-5 py-20 lg:grid-cols-[1fr_1fr] lg:px-10 lg:py-24"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#f8d6ca]">03 / La tienda</p><h2 className="mt-4 max-w-lg font-display text-5xl font-bold leading-[.92] tracking-[-.06em] md:text-6xl">La colección<br />también se<br /><span className="text-[#d9eb4b]">juega.</span></h2></div><div className="flex flex-col justify-end"><p className="max-w-md text-lg leading-7 text-[#fbe4dd]">Élite 4 TCG nace para hacer que comprar cartas vuelva a sentirse como descubrir un tesoro. Producto honesto, envíos cuidados a todo México y una comunidad que no necesita explicarse.</p><div className="mt-10 grid gap-4 border-t border-[#f2a18f] pt-6 sm:grid-cols-3"><div><Truck size={20} className="text-[#d9eb4b]" /><p className="mt-3 text-sm font-bold">Envío nacional</p><p className="mt-1 text-xs text-[#f8d6ca]">Protegido hasta tu puerta.</p></div><div><PackageCheck size={20} className="text-[#d9eb4b]" /><p className="mt-3 text-sm font-bold">Producto real</p><p className="mt-1 text-xs text-[#f8d6ca]">Stock claro, sin humo.</p></div><div><ShieldCheck size={20} className="text-[#d9eb4b]" /><p className="mt-3 text-sm font-bold">Compra tranquila</p><p className="mt-1 text-xs text-[#f8d6ca]">Soporte de persona a persona.</p></div></div></div></div></section>
    </main>
    <footer className="bg-[#12282f] px-5 py-10 text-[#f5f0e6] lg:px-10"><div className="mx-auto flex max-w-[1400px] flex-col justify-between gap-8 md:flex-row md:items-end"><div><a href="#inicio" className="font-display text-2xl font-bold" data-testid="footer-logo">Élite 4 TCG<span className="text-[#d9eb4b]">.</span></a><p className="mt-3 max-w-xs text-sm leading-6 text-[#9badA7]">La tienda TCG para coleccionar, jugar y proteger tus cartas en México.</p></div><div className="flex flex-wrap gap-x-6 gap-y-3 text-sm text-[#c2cfca]"><a href="#catalogo" className="hover:text-[#d9eb4b]" data-testid="footer-link-catalogo">Catálogo</a><a href="mailto:contacto@elite4tcg.mx" className="hover:text-[#d9eb4b]" data-testid="link-contact-email">contacto@elite4tcg.mx</a><a href="#inicio" className="hover:text-[#d9eb4b]" data-testid="footer-link-top">Volver arriba ↑</a></div></div><div className="mx-auto mt-10 max-w-[1400px] border-t border-[#34434a] pt-4 font-mono text-[10px] uppercase tracking-[.12em] text-[#71807a]">© 2026 Élite 4 TCG · Hecho para jugar, guardar y compartir.</div></footer>
    {toast && <div className="fixed bottom-5 left-1/2 z-[70] flex -translate-x-1/2 items-center gap-3 bg-[#12282f] px-5 py-3 text-sm font-semibold text-[#f5f0e6] shadow-xl animate-rise" data-testid="status-toast"><Check size={16} className="text-[#d9eb4b]" />{toast}</div>}
    <CartDrawer open={cartOpen} items={cart} onClose={() => setCartOpen(false)} onChange={changeQuantity} onRemove={removeItem} onCheckout={openCheckout} />
    <ProductModal product={selected} mode={modalMode} onClose={() => { setSelected(null); setModalMode(null); }} onAdd={addToCart} />
    {authOpen && <AuthModal onClose={() => setAuthOpen(false)} onLogin={onLogin} />}
    {checkoutOpen && user && <CheckoutModal user={user} subtotal={subtotal} onClose={() => setCheckoutOpen(false)} onComplete={completeOrder} />}
  </div>;
}

export default App;